pointLocator.script:
time_polling_min = 1;
time_polling_seg = time_polling_min * 60;
time_polling_ms = time_polling_seg * 1000;

if(corriente_fase_a.time == null){
    status.set(0.0);
}else{
    if(Date.now() - corriente_fase_a.time > time_polling_ms) 
    {
        status.set(0.0);
    }
    else 
    {
        status.set(1.0);
    }
}
 return 1;
